import React, { useState } from "react";
import Login from "./Login";
import Admin from "./Admin";
import Drivers from "./Drivers";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("admin_token"));
  const [page, setPage] = useState("requests");

  if (!token) {
    return (
      <Login
        onLogin={() => {
          localStorage.setItem("admin_token", "yes");
          setToken("yes");
        }}
      />
    );
  }

  return (
    <>
      <div style={{ display: "flex", gap: 20, padding: 10 }}>
        <button onClick={() => setPage("requests")}>Requests</button>
        <button onClick={() => setPage("drivers")}>Drivers</button>
        <button
          onClick={() => {
            localStorage.removeItem("admin_token");
            setToken(null);
          }}
        >
          Logout
        </button>
      </div>

      {page === "requests" && <Admin />}
      {page === "drivers" && <Drivers />}
    </>
  );
}
